    panel.addEventListener("click", (event) => {
      const action = event.target?.dataset?.action;
      const background = event.target?.dataset?.bg;
      if (background) {
        this.simpleAnim.background = background;
        this.renderUi();
        return;
      }
      if (!action) return;
      if (action === "reset") this.resetSimpleAnim();
